let cursor: string | undefined
do {
  const page = await api.users.list({ cursor, limit: 50 })
  for (const u of page.data) process(u)
  cursor = page.next_cursor
} while (cursor)

let url: string | undefined = '/users?limit=50'
while (url) {
  const res = await fetch(url)
  for (const u of await res.json()) process(u)
  url = parseLink(res.headers.get('link'))?.next
}
